// Combines Tibber price data with solar forecast into a unified array.
//
// Input:  msg.payload.tibber   - array of price objects from Tibber API (hourly or quarter-hourly)
//         msg.payload.forecast - optional array of 24 solar forecast values (one per hour)
//
// Output: msg.payload.ret.data - array of 24 (hourly) or 96 (quarter-hourly) objects:
//           datum      : "YYYY-MM-DD HH:MM:SS"
//           hour_price : price in EUR/kWh
//           level      : Tibber price level (e.g. CHEAP, NORMAL, EXPENSIVE)
//           forecast   : solar forecast value for that hour (0 if unavailable)
//
// DST handling:
//   Winter→summer (23h/92q): the skipped 02:00 hour is filled by copying the 01:xx price/level.
//   Summer→winter (25h/100q): the repeated 02:00 hour is deduplicated (first occurrence kept).
//   Output always contains exactly 24 or 96 entries.

var ret = {};
var json = msg.payload.tibber;

ret.datum = json[0].startsAt.substr(0, 10);

// Tibber prices in Hours or Quarters only
// Also accept DST transition days: 23h/92q (winter→summer) or 25h/100q (summer→winter)
var len = json.length;
if (len != 23 && len != 24 && len != 25 && len != 92 && len != 96 && len != 100) {
    ret.status = false;
    msg.payload = ret;
    return msg;
}

var isQuarterly = (len >= 92);
var expectedCount = isQuarterly ? 96 : 24;
var stepMinutes = isQuarterly ? 15 : 60;

// Summer→winter DST: one local hour appears twice — deduplicate, keeping first occurrence
if (len > expectedCount) {
    var seen = {};
    json = json.filter(function(item) {
        var timeKey = item.startsAt.substr(11, 5); // HH:MM
        if (seen[timeKey]) return false;
        seen[timeKey] = true;
        return true;
    });
}

// Winter→summer DST: one local hour is missing — fill it by copying the previous slot's values
if (json.length < expectedCount) {
    var timeMap = {};
    json.forEach(function(item) { timeMap[item.startsAt.substr(11, 5)] = item; });

    var filled = [];
    var prevItem = json[0];
    for (var slot = 0; slot < expectedCount; slot++) {
        var totalMin = slot * stepMinutes;
        var h = Math.floor(totalMin / 60);
        var m = totalMin % 60;
        var timeKey = ('0' + h).slice(-2) + ':' + ('0' + m).slice(-2);
        if (timeMap[timeKey]) {
            prevItem = timeMap[timeKey];
        } else {
            // Synthesise missing slot from previous entry, keeping its price/level
            var tzPart = prevItem.startsAt.substr(19);
            prevItem = Object.assign({}, prevItem, {
                startsAt: prevItem.startsAt.substr(0, 11) + timeKey + ':00' + tzPart
            });
        }
        filled.push(prevItem);
    }
    json = filled;
}

ret.status = true;

//Check if forecast has 24 values, otherwise it's invalid!
var varray = msg.payload.forecast || [];
var bHaveForecast = (varray.length == 24);

// Transform array of objects
ret.data = json.map(item => ({
                    datum: ret.datum + " " + item.startsAt.substr(11, 8),
                    hour_price: item.total,
                    level: item.level,
                    forecast: (bHaveForecast == true) ? varray[parseInt(item.startsAt.substr(11, 2))] : 0
                }));

msg.payload = ret;
return msg;

