function makePlan(data, label) {
    const rows = [];
    let lastState        = "";
    let prevV            = null;
    let blockStartTime   = null;
    let blockStartEarned = 0;
    let lastEarned       = 0;

    for (let h = 0; h < 24; h++) {
        for (const m of MINS) {
            const key = ("0" + h).slice(-2) + ":" + m;
            const v = data[key];
            if (!v) continue;
            if (v.hour_type !== lastState) {
                if (lastState !== "" && blockStartTime !== null) {
                    rows.push({ start: blockStartTime, end: key, type: lastState,
                                socEnd: prevV.battery_capacity_percentage,
                                delta: prevV.earned_money - blockStartEarned });
                }
                if (v.hour_type !== "idle") {
                    lastState        = v.hour_type;
                    blockStartTime   = key;
                    blockStartEarned = prevV ? prevV.earned_money : 0;
                } else {
                    lastState      = "";
                    blockStartTime = null;
                }
            }
            if (v.earned_money != null) lastEarned = v.earned_money;
            prevV = v;
        }
    }
    if (lastState !== "" && blockStartTime !== null && prevV) {
        rows.push({ start: blockStartTime, end: null, type: lastState,
                    socEnd: prevV.battery_capacity_percentage,
                    delta: prevV.earned_money - blockStartEarned });
    }

    const d = new Date(data.datum + 'T00:00:00');
    const dateLabel = d.getDate() + ' ' + MON[d.getMonth()];
    const title = 'Battery plan ' + (label === 'TD' ? 'today' : 'tomorrow') + ' (' + dateLabel + ')';

    let html = '<div class="bp-col">';
    html += '<h4><span><i class="fa fa-calendar"></i> ' + title + '</span>';
    if (rows.length > 0) {
        const totalEarned = rows.reduce((sum, r) => sum + r.delta, 0);
        html += '<span class="bp-earn">&euro; ' + totalEarned.toFixed(2) + '</span>';
    }
    html += '</h4>';

    if (rows.length === 0) {
        html += '<div style="color:#c8a0ff;font-style:italic;font-size:.82em;padding:6px 10px;">' +
                (label === 'TD' ? 'Today' : 'Tomorrow') + ' no charge day...</div>';
    } else {
        const typeClass = {
            'charge':       'bp-chg',
            'discharge':    'bp-dis',
            'solarbalance': 'bp-sol',
            'nightbalance': 'bp-night'
        };
        for (const r of rows) {
            const tc = typeClass[r.type] || 'bp-dis';
            html += '<div class="bp-row">';
            html += '<span class="bp-time">' + r.start + ' &rarr; ' + (r.end || 'end') + '</span>';
            html += '<span class="bp-type-cell"><span class="bp-type ' + tc + '">' + r.type + '</span></span>';
            html += '<span class="bp-right">' +
                    '<span class="bp-bat"><i class="fa fa-battery-half"></i> ' + Math.round(r.socEnd) + '%</span>' +
                    '<span class="bp-price">&euro; ' + r.delta.toFixed(2) + '</span>' +
                    '</span>';
            html += '</div>';
        }
    }
    html += '</div>';
    return html;
}

const pad = n => ('0' + n).slice(-2);
const now      = new Date();
const tomorrow = new Date(now.getTime() + 86400000);
const todayStr    = now.getFullYear()      + '-' + pad(now.getMonth()+1)      + '-' + pad(now.getDate());
const tomorrowStr = tomorrow.getFullYear() + '-' + pad(tomorrow.getMonth()+1) + '-' + pad(tomorrow.getDate());

const schemeToday    = context.global.scheme_today;
const schemeTomorrow = context.global.scheme_tomorrow;

const cols = [];

if (schemeToday && schemeToday.status === true && schemeToday.datum === todayStr) {
    cols.push(makePlan(schemeToday, 'TD'));
} else {
    cols.push('<div class="bp-col"><h4><span>Battery plan today</span></h4>' +
              '<div style="padding:6px 10px;color:red;">No today data</div></div>');
}

if (schemeTomorrow && schemeTomorrow.status === true && schemeTomorrow.datum === tomorrowStr) {
    cols.push(makePlan(schemeTomorrow, 'TM'));
} else if (now.getHours() >= 15) {
    cols.push('<div class="bp-col"><h4><span>Battery plan tomorrow</span></h4>' +
              '<div style="padding:6px 10px;color:red;">No tomorrow data</div></div>');
}

msg.payload = CSS + '<div class="bp"><div class="bp-wrap">' + cols.join('') + '</div></div>';
msg.topic   = 'batt_plan_text';
msg.retain  = true;
return msg;

/*
 * OptimusPrime — Battery Charge/Discharge Optimizer
 * Version: 10
 *
 * OVERVIEW
 * --------
 * Calculates the optimal charge/discharge schedule for a home battery
 * against Tibber quarter-hour electricity prices using dynamic programming.
 *
 * Improvements over OP3 (v1.11) based on OP4:
 *   - Real battery SOC as DP start point (OP3 always assumed batt_min / 10%)
 *   - Joint today+tomorrow optimization in a single DP pass, so cross-day
 *     decisions are possible (e.g. don't fully discharge today if tomorrow
 *     morning has cheap buy prices)
 *   - Stores context.global.scheme_today as an indexed object ("HH:MM" → slot)
 *     for fast current-slot lookup and cross-day re-optimization
 *   - noChargeAfterLastDischarge applied per-day (not across the combined span)
 *   - Solar forecast hook (disabled by default, set USE_SOLAR_FORECAST = true)
 *
 * v5.1 changes:
 *   - applySolarBalanceFill: replaced the 'CHEAP' level filter with an
 *     efficiency-aware profitability test. Solar is captured only when
 *     discharge_eff × best_future_discharge_price > current_export_price.
 *     earnedDelta now reflects the net gain over direct export rather than
 *     the full slot price, and a suffix-maximum pre-pass makes lookup O(1).
 *   - applyNightBalanceFill: removed. HomeBattHE already holds grid consumption
 *     at zero continuously; the function was redundant. If explicit per-slot
 *     battery-over-grid control is needed, use the existing 'gridbalance' type.
 *
 * HOW THE DP WORKS
 * ----------------
 * The state space is battery energy level, discretised into steps of
 * gcd(charge_rate, discharge_rate) Wh. For each 15-minute slot the algorithm
 * considers three actions per reachable state:
 *
 *   IDLE      → stay at current level, profit unchanged
 *   CHARGE    → move up one charge step, pay  (energy_in  / charge_eff)  * price
 *   DISCHARGE → move down one discharge step, earn (energy_out * discharge_eff) * price
 *
 * A forward pass fills dp[k] = best profit reachable with k steps above batt_min.
 * A backward trace through the action/from arrays reconstructs the decision sequence.
 *
 * RUNNING STANDALONE (outside Node-RED)
 * --------------------------------------
 *   node runner.js                  → uses today1.json
 *   node runner.js today2.json      → use a different price file
 *
 * runner.js sets up the simulated globals in the CONFIG section below and
 * calls the exported functions directly.
 *
 * NODE-RED USAGE
 * --------------
 * Paste everything between CUT HERE markers into the OptimusPrime function node.
 * The Node-RED context API (context.global / context.flow) replaces the
 * standalone CONFIG section automatically.
 *
 * INPUT  (msg.payload):  { datum, status, data: [96 slot objects] }
 *         msg.topic:     "scheme_today"    → today-only DP (00:01 / restart)
 *                        "scheme_tomorrow" → joint today+tomorrow DP (14:01 / 15:01)
 *
 * OUTPUT (msg.payload):  { datum, status, data: [96 slot objects with added fields] }
 *         Per-slot added fields: hour_type, setpoint, battery_capacity_watt,
 *                                battery_capacity_percentage, earned_money
 *
 * Node-RED outputs:
 *   Output 1 → scheme_today  (topic: tibber_data/scheme_today/state)
 *   Output 2 → scheme_tomorrow (topic: tibber_data/scheme_tomorrow/state)
 *
 * Context writes:
 *   context.global.scheme_today            – indexed object ("HH:MM" → slot)
 *   context.global.scheme_tomorrow         – indexed object ("HH:MM" → slot)
 *   context.global.charge_scheme_today     – { status, datum, data: [...] } array format
 *   context.global.charge_scheme_tomorrow  – { status, datum, data: [...] } array format
 */

// ═══════════════════════════════════════════════════════════════════════════════
// STANDALONE CONFIG  (used only when running via runner.js, not in Node-RED)
// In Node-RED these values come from context.global / context.flow instead.
// ═══════════════════════════════════════════════════════════════════════════════

const STANDALONE = (typeof context === "undefined");

const CONFIG = {
    // ── Battery hardware ──────────────────────────────────────────────────────
    batt_capacity:             46300,   // Wh  – 14300 + 16000 + 16000 (3 × battery packs)
    number_of_multiplus:           3,   // informational – number of Multiplus inverters

    // Charge: batt_charge_rate is the power used for DP energy calculation.
    //         max_charge_setpoint is the ESS setpoint commanded to the inverter.
    batt_charge_rate:           9000,   // W   – charge power basis for DP (grid → battery)
    max_charge_setpoint:       10000,   // W   – ESS setpoint sent during charge slots
    batt_charge_efficiency:    0.907,   // –    energy stored in battery / energy drawn from grid

    // Discharge: batt_discharge_rate is the power used for DP energy calculation.
    //            max_discharge_setpoint is the ESS setpoint commanded to the inverter.
    batt_discharge_rate:        9000,   // W   – discharge power basis for DP (battery → grid)
    max_discharge_setpoint:    10000,   // W   – ESS setpoint sent during discharge slots (negated in output)
    batt_discharge_efficiency: 0.930,   // –    energy delivered to grid / energy drawn from battery

    // ── SOC limits ────────────────────────────────────────────────────────────
    min_soc:                      10,   // %   – lower SOC floor (batt_min_charged derived from this)
    max_soc:                     100,   // %   – upper cap; 100% = physical ~90% via SmartShunt (55.2 V = 100%)
    // batt_min_charged is derived below: min_soc/100 × batt_capacity

    // ── Idle consumption ─────────────────────────────────────────────────────
    idle_rate:                   110,   // W   – standby draw / ESS setpoint when battery is idle

    // ── Per-phase limit (used by Watt/kWh/Log/Monitor flow to guard grid overload)
    max_phase_power:            5550,   // W   – max power per phase

    // ── Trading parameters ────────────────────────────────────────────────────
    price_min_sell_difference:  0.06,   // EUR/kWh – min spread above buy price to consider selling

    // ── Simulation: current SOC for standalone testing ────────────────────────
    batt_soc:                     50,   // %   – simulated current SOC (set null to use batt_min fallback)

    // ── Feature flags ─────────────────────────────────────────────────────────
    USE_SOLAR_FORECAST: false,
    // In Node-RED: read from context.flow.USE_SOLAR_FORECAST (set by Global Variables node).
    // When true, solar forecast values in slot.forecast (W average) will
    // reduce the effective "need to charge from grid" by reducing the charge
    // cost. Currently disabled; requires forecast calibration for your location.

};

// batt_min_charged is derived from min_soc × batt_capacity.
// In Node-RED the init function pre-computes this into context.flow.batt_min_charged.
// In standalone mode we derive it here so the F() adapter finds it in CONFIG.
CONFIG.batt_min_charged = CONFIG.batt_capacity * CONFIG.min_soc / 100;

// ── Adapter: in Node-RED these come from context.global / context.flow.
//    In standalone mode they come from CONFIG above.
function G(key) { return STANDALONE ? CONFIG[key] : context.global[key]; }
function F(key) { return STANDALONE ? CONFIG[key] : context.flow[key];   }
function GD(key) {
    // Reads context.global.data[key] (live Victron state) in Node-RED.
    // In standalone, returns the simulated value from CONFIG.
    if (STANDALONE) return (key === "batt_soc") ? CONFIG.batt_soc : undefined;
    const d = context.global.data;
    return (d != null) ? d[key] : undefined;
}

// ── Warn/log adapter ─────────────────────────────────────────────────────────
function warn(msg) {
    if (STANDALONE) { console.warn("[OP9]", msg); }
    else            { node.warn("OP9: " + msg); }
}

// ═══════════════════════════════════════════════════════════════════════════════
// HELPERS — Scheme indexed-object format ("HH:MM" → slot)
// The internal scheme_today is stored as an indexed object for O(1) lookup.
// The MQTT output uses the original array format (consumed by Domoticz BattIQMode).
// ═══════════════════════════════════════════════════════════════════════════════

const MINS = ["00", "15", "30", "45"];

/** Build indexed scheme object from a flat result array.
 *  Returns { status:true, datum, "00:00":{slot}, "00:15":{slot}, ... }
 */
function buildSchemeObj(datum, slotsArray) {
    const obj = { status: true, datum: datum, num_records: slotsArray.length };
    slotsArray.forEach(function(slot, idx) {
        const h = Math.floor(idx / 4);
        const m = idx % 4;
        const key = ("0" + h).slice(-2) + ":" + MINS[m];
        obj[key] = slot;
    });
    return obj;
}

/** Convert indexed scheme back to flat array (price/metadata only, no schedule fields).
 *  Used to feed remaining today slots into the joint DP.
 */
function schemeObjToArray(scheme) {
    const arr = [];
    for (let h = 0; h < 24; h++) {
        for (let m = 0; m < 4; m++) {
            const key = ("0" + h).slice(-2) + ":" + MINS[m];
            if (scheme[key] != null) arr.push(scheme[key]);
        }
    }
    return arr;
}

/** Merge DP-updated slots back into an existing indexed scheme.
 *  Preserves price/level/forecast fields from the original; overwrites
 *  schedule fields (hour_type, setpoint, battery_capacity_watt, etc.).
 */
function updateSchemeObj(scheme, startSlotIdx, updatedSlots) {
    const updated = JSON.parse(JSON.stringify(scheme));
    for (let i = 0; i < updatedSlots.length; i++) {
        const slotIdx = startSlotIdx + i;
        const h = Math.floor(slotIdx / 4);
        const m = slotIdx % 4;
        const key = ("0" + h).slice(-2) + ":" + MINS[m];
        updated[key] = Object.assign({}, updated[key] || {}, updatedSlots[i]);
    }
    return updated;
}

/** Return the "HH:MM" key for the current 15-minute slot (rounds down to 00/15/30/45). */
function currentSlotKey() {
    const now = new Date();
    const m = Math.floor(now.getMinutes() / 15) * 15;
    return ("0" + now.getHours()).slice(-2) + ":" + ("0" + m).slice(-2);
}

/** Return the flat index (0–95) of the current 15-minute slot. */
function currentSlotIdx() {
    const now = new Date();
    return now.getHours() * 4 + Math.floor(now.getMinutes() / 15);
}

// ═══════════════════════════════════════════════════════════════════════════════
// HELPERS — SOC
// ═══════════════════════════════════════════════════════════════════════════════

/** Return the starting SOC in Wh for the DP.
 *  Prefers the live SOC reading from the Victron system.
 *  Falls back to batt_min_charged (same behaviour as OP3) if no live data.
 */
function getStartSocWatt() {
    const battSocPct = GD("batt_soc");
    if (battSocPct != null) {
        return G("batt_capacity") * battSocPct / 100;
    }
    warn("batt_soc not available, falling back to batt_min");
    return F("batt_min_charged");
}

// ═══════════════════════════════════════════════════════════════════════════════
// HELPERS — Solar balance fill
//
// Post-DP pass: promote idle slots with net solar surplus (forecast > HOUSE_LOAD_W)
// to 'solarbalance' when storing in the battery and discharging later is strictly
// more profitable than exporting to the grid immediately.
//
// Economics per slot at export price p_export:
//   Export now:        solar_Wh × p_export                          (no efficiency loss)
//   Store + discharge: solar_Wh × discharge_eff × p_discharge_best  (discharge loss only)
//
// Capture iff:  discharge_eff × p_discharge_best  >  p_export
//
// Note: charge_efficiency is NOT part of this decision. Solar energy arrives for
// free — no grid tariff is paid to fill the battery from PV. Only the discharge
// path carries an efficiency penalty.
//
// A suffix-maximum pre-pass computes the best future discharge price at each
// position in O(n), so the per-slot test is O(1).
//
// When no future discharge slot exists (suffix max == 0) the battery route yields
// nothing and direct export is always preferred.
//
// Skips the pass entirely when the DP already fills the battery — no benefit then.
// ═══════════════════════════════════════════════════════════════════════════════

function applySolarBalanceFill(schedule, startSocWatt) {
    const HOUSE_LOAD_W   = G("solar_min_surplus_w") || 800;
    const bIsQuarterData = schedule.length > 24;
    const blockMult      = bIsQuarterData ? 0.25 : 1.0;

    const batt_max          = G("batt_capacity") * G("max_soc") / 100;
    const batt_min          = F("batt_min_charged");
    const dischargeEff      = G("batt_discharge_efficiency") || 0.930;
    const calcChargeRate    = G("batt_charge_rate") * blockMult;
    const calcDischargeRate = G("batt_discharge_rate") * blockMult;

    // Note: the former early-exit ("skip entirely when DP fills battery") was removed.
    // It caused two bugs:
    //  1. It fired whenever overnight charging hit 100%, which is almost every joint run.
    //  2. It returned `schedule` with battery_capacity_percentage values from the DP
    //     simulation — BEFORE applyNoChargeAfterLastDischarge removed the trailing charge
    //     slots. The displayed end-of-day SOC was therefore inflated (stale).
    //  3. It blocked legitimate solarbalance promotions in afternoon slots that had
    //     available capacity (after morning discharges brought the battery below max).
    // The loop below naturally skips solarbalance when availCap == 0, so no early exit
    // is needed. battery_capacity_percentage is always recomputed from the updated
    // hour_type sequence, giving a correct SOC trajectory regardless.

    const n = schedule.length;

    // Pre-compute suffix maximum of discharge slot prices.
    // bestFutureDischargePrice[i] = highest hour_price among discharge slots
    // at indices i+1 … n-1.  Value is 0.0 when no discharge slot follows index i.
    const bestFutureDischargePrice = new Float64Array(n).fill(0.0);
    for (let i = n - 2; i >= 0; i--) {
        bestFutureDischargePrice[i] = bestFutureDischargePrice[i + 1];
        if (schedule[i + 1].hour_type === 'discharge') {
            bestFutureDischargePrice[i] = Math.max(
                bestFutureDischargePrice[i],
                schedule[i + 1].hour_price
            );
        }
    }

    const result    = JSON.parse(JSON.stringify(schedule));
    let battLevel   = Math.min(batt_max, Math.max(batt_min, startSocWatt));
    let earnedDelta = 0.0; // cumulative net gain (EUR) from solarbalance promotions

    for (let i = 0; i < result.length; i++) {
        const slot = result[i];

        if (slot.hour_type === 'idle') {
            const solarSurplus = Math.max(0, (slot.forecast || 0) - HOUSE_LOAD_W);
            const availCap     = batt_max - battLevel;

            if (solarSurplus > 0 && availCap > 0) {
                const p_export    = slot.hour_price;
                const p_discharge = bestFutureDischargePrice[i]; // 0 if no future discharge slot
                const battYield   = p_discharge * dischargeEff;  // EUR/kWh after discharge loss

                // Only capture solar when the battery route beats direct grid export.
                // When p_discharge == 0 there are no future sell opportunities — export wins.
                if (battYield > p_export) {
                    const solarCharge = Math.min(solarSurplus * blockMult, availCap);
                    slot.hour_type = 'solarbalance';
                    slot.setpoint  = G("idle_rate") || 110;
                    battLevel     += solarCharge;
                    // Incremental gain over exporting now:
                    //   battery route:  solarCharge/1000 × battYield
                    //   export now:     solarCharge/1000 × p_export
                    //   delta:          solarCharge/1000 × (battYield − p_export)
                    earnedDelta += (solarCharge / 1000) * (battYield - p_export);
                }
                // else: leave idle — solar exports to grid at p_export; no earnedDelta added
            }
        } else if (slot.hour_type === 'charge') {
            const add = Math.min(calcChargeRate, batt_max - battLevel);
            battLevel = Math.min(batt_max, battLevel + add);
        } else if (slot.hour_type === 'discharge') {
            const sub = Math.min(calcDischargeRate, battLevel - batt_min);
            battLevel = Math.max(batt_min, battLevel - sub);
        }

        slot.battery_capacity_watt       = Math.round(battLevel);
        slot.battery_capacity_percentage = parseFloat(((100.0 / batt_max) * battLevel).toFixed(2));
        slot.earned_money                = Math.round((slot.earned_money + earnedDelta) * 10000) / 10000;
    }

    return result;
}

// ═══════════════════════════════════════════════════════════════════════════════
// HELPERS — Validation
// ═══════════════════════════════════════════════════════════════════════════════

/** Validate incoming Tibber payload.
 *  allowFutureDays: 0 = today only, 1 = today or tomorrow, etc.
 */
function sanityCheck(json, allowFutureDays) {
    if (allowFutureDays === undefined) allowFutureDays = 0;
    if (!json || json.status !== true) {
        warn("sanityCheck failed: status != true");
        return false;
    }
    const jDate = new Date(json.datum + 'T00:00:00'); // no Z → parsed as local midnight
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const maxDate = new Date(today);
    maxDate.setDate(maxDate.getDate() + allowFutureDays + 1); // exclusive upper bound
    if (jDate.getTime() < today.getTime() || jDate.getTime() >= maxDate.getTime()) {
        warn("sanityCheck failed: datum " + json.datum + " out of range (allowFutureDays=" + allowFutureDays + ")");
        return false;
    }
    if (!Array.isArray(json.data) || json.data.length < 24) {
        warn("sanityCheck failed: data array too short (" + (json.data ? json.data.length : 0) + ")");
        return false;
    }
    return true;
}

// ═══════════════════════════════════════════════════════════════════════════════
// HELPERS — noChargeAfterLastDischarge
// Removes charge slots that appear after the last discharge in a day-range.
// Rationale: charging after you've finished selling is pointless — you'd be
// buying expensive evening power just to top up, with no sale planned.
// Applied per-day (not across combined today+tomorrow span).
// ═══════════════════════════════════════════════════════════════════════════════

/** In slots[start..end), find the last discharge and set any later charge → idle. */
function applyNoChargeAfterLastDischarge(slots, start, end) {
    let lastDischarge = -1;
    for (let i = end - 1; i >= start; i--) {
        if (slots[i].hour_type === "discharge") { lastDischarge = i; break; }
    }
    if (lastDischarge === -1) return;
    for (let i = lastDischarge + 1; i < end; i++) {
        if (slots[i].hour_type === "charge") {
            slots[i].hour_type = "idle";
            slots[i].setpoint  = G("idle_rate") || 0;
        }
    }
}

// ═══════════════════════════════════════════════════════════════════════════════
// CORE ALGORITHM — Forward DP
//
// State: k = number of charge steps above batt_min  (k=0 → battery at batt_min)
// Step size: gcd(charge_rate, discharge_rate) Wh — prevents energy aliasing
//   where two different paths reach the same SOC level with the same step
// Profit: EUR, positive = earned money, negative = spent money
//
// For each slot i, for each reachable state k:
//   IDLE:      newDp[k]    = max(newDp[k],    dp[k])
//   CHARGE:    newDp[k+Δ]  = max(newDp[k+Δ],  dp[k] - cost_to_charge)
//   DISCHARGE: newDp[k-Δ]  = max(newDp[k-Δ],  dp[k] + gain_from_discharge)
//
// After the forward pass: backtrack through btAction/btFrom arrays to recover
// the optimal action sequence, then simulate forward to compute SOC and earnings.
// ═══════════════════════════════════════════════════════════════════════════════

function gcd(a, b) { while (b) { var t = b; b = a % b; a = t; } return a; }

/**
 * @param {Array}   data                      - Array of slot objects (price/forecast input)
 * @param {number}  startSocWatt              - Battery energy at start of first slot (Wh)
 * @param {boolean} noChargeAfterLastDischarge - If true, strip trailing charge slots per-day
 *                                              Set false for joint data (handled externally)
 * @param {number}  startEarnedMoney          - Carry-over earned money from prior slots (EUR)
 * @returns {Array} Input array augmented with hour_type, setpoint, battery_capacity_watt,
 *                  battery_capacity_percentage, earned_money per slot
 */
function calculate_charge_schema(data, startSocWatt, noChargeAfterLastDischarge, startEarnedMoney) {
    if (noChargeAfterLastDischarge === undefined) noChargeAfterLastDischarge = true;
    if (startEarnedMoney          === undefined) startEarnedMoney = 0.0;

    const processedData = JSON.parse(JSON.stringify(data));
    const n = processedData.length;

    // Quarter-hour data has 96 slots/day; hourly has 24.
    // blockMultiply converts power (W) to energy per slot (Wh): 0.25h for quarters, 1h for hourly.
    const bIsQuarterData = (n > 24);
    const blockMultiply  = bIsQuarterData ? 0.25 : 1.0;

    // ── Battery parameters ───────────────────────────────────────────────────
    const charge_efficiency    = G("batt_charge_efficiency")    || 0.907;
    const discharge_efficiency = G("batt_discharge_efficiency") || 0.930;
    const batt_min             = F("batt_min_charged");
    const batt_max             = G("batt_capacity") * G("max_soc") / 100;

    // Energy added to battery per charge slot (Wh): charge_rate drawn from grid × eff
    const calc_charge_rate = G("batt_charge_rate") * blockMultiply;

    // Energy removed from battery per discharge slot (Wh):
    // The inverter exports max_discharge_setpoint W to the grid.
    // Due to discharge efficiency losses the battery must supply more:
    //   battery_drain = grid_export / discharge_efficiency
    const calc_discharge_rate = G("batt_discharge_rate") * blockMultiply;

    const priceDiff = F("price_min_sell_difference") || 0.02;

    // ── DP discretisation ────────────────────────────────────────────────────
    // Step size = gcd of charge and discharge rates → smallest common energy unit.
    // Enforced minimum of 100 Wh: discharge_efficiency (0.930) makes the raw gcd=1 Wh,
    // which creates ~41 000 DP levels and blocks the Node.js event loop for 30+ seconds.
    // 100 Wh precision is sufficient (< 0.3 % of 46 kWh battery).
    const MIN_STEP  = 100;
    const calc_step = Math.max(MIN_STEP, gcd(Math.round(calc_charge_rate), Math.round(calc_discharge_rate)));
    const maxLevel  = Math.ceil((batt_max - batt_min) / calc_step);

    function socAtLevel(k) { return Math.min(batt_max, batt_min + k * calc_step); }

    // Map startSocWatt to the nearest grid level (clamped to valid range)
    const clampedStart = Math.min(batt_max, Math.max(batt_min, startSocWatt));
    const startLevel   = Math.min(maxLevel, Math.max(0, Math.round((clampedStart - batt_min) / calc_step)));

    // ── Forward DP ───────────────────────────────────────────────────────────
    let dp = new Float64Array(maxLevel + 1).fill(-Infinity);
    dp[startLevel] = 0.0;  // start with 0 profit at the actual SOC level

    // btAction[slot * (maxLevel+1) + level] = best action to reach this state
    // btFrom  [slot * (maxLevel+1) + level] = level we came from
    const btAction = new Uint8Array(n * (maxLevel + 1));
    const btFrom   = new Uint32Array(n * (maxLevel + 1));
    const ACTION_IDLE = 0, ACTION_CHARGE = 1, ACTION_DISCHARGE = 2;

    for (let i = 0; i < n; i++) {
        const price = processedData[i].hour_price;
        const newDp = new Float64Array(maxLevel + 1).fill(-Infinity);
        const base  = i * (maxLevel + 1);

        for (let k = 0; k <= maxLevel; k++) {
            if (dp[k] === -Infinity) continue;
            const soc = socAtLevel(k);

            // IDLE: stay at level k
            if (dp[k] > newDp[k]) {
                newDp[k]          = dp[k];
                btAction[base + k] = ACTION_IDLE;
                btFrom[base + k]   = k;
            }

            // CHARGE: buy energy from grid, fill battery
            if (soc < batt_max) {
                const chargeEnergy = Math.min(calc_charge_rate, batt_max - soc);
                const newK         = Math.min(maxLevel, Math.ceil((soc + chargeEnergy - batt_min) / calc_step));
                // Cost: energy drawn from grid = chargeEnergy / charge_efficiency
                const cost   = (chargeEnergy / charge_efficiency / 1000) * price;
                const profit = dp[k] - cost;
                if (profit > newDp[newK]) {
                    newDp[newK]          = profit;
                    btAction[base + newK] = ACTION_CHARGE;
                    btFrom[base + newK]   = k;
                }
            }

            // DISCHARGE: sell energy to grid.
            // Require a FULL discharge step to be available (soc - batt_min >= calc_discharge_rate).
            // Partial discharges (less than one full step) are excluded because they create a
            // spurious charge→partial-discharge arbitrage cycle: charging earns more EUR per Wh
            // than the partial discharge costs, even at uniform prices, due to the asymmetry
            // between charge efficiency and discharge efficiency. Requiring a full step ensures
            // the DP only discharges when there is genuinely enough energy for a complete action.
            if (soc - batt_min >= calc_discharge_rate) {
                const dischargeEnergy = calc_discharge_rate;
                const newK            = Math.max(0, Math.floor((soc - dischargeEnergy - batt_min) / calc_step));
                // Gain: energy delivered to grid = dischargeEnergy * discharge_efficiency
                // Only sell if price exceeds priceDiff threshold (avoids near-zero arbitrage)
                const gain   = (dischargeEnergy * discharge_efficiency / 1000) * (price - priceDiff);
                const profit = dp[k] + gain;
                if (profit > newDp[newK]) {
                    newDp[newK]          = profit;
                    btAction[base + newK] = ACTION_DISCHARGE;
                    btFrom[base + newK]   = k;
                }
            }
        }

        dp = newDp;
    }

    // ── Find best end state ───────────────────────────────────────────────────
    let bestProfit = -Infinity, bestEndLevel = 0;
    for (let k = 0; k <= maxLevel; k++) {
        if (dp[k] > bestProfit) { bestProfit = dp[k]; bestEndLevel = k; }
    }

    // ── Backward trace — recover action sequence ──────────────────────────────
    const actionSeq = new Array(n);
    let curLevel = bestEndLevel;
    for (let i = n - 1; i >= 0; i--) {
        const base = i * (maxLevel + 1);
        const a = btAction[base + curLevel];
        actionSeq[i] = (a === ACTION_CHARGE) ? "charge" : (a === ACTION_DISCHARGE) ? "discharge" : "idle";
        curLevel = btFrom[base + curLevel];
    }

    processedData.forEach(function(item, i) { item.hour_type = actionSeq[i]; });

    // ── Per-day noChargeAfterLastDischarge (if requested) ─────────────────────
    if (noChargeAfterLastDischarge) {
        applyNoChargeAfterLastDischarge(processedData, 0, n);
    }

    // ── Forward simulation — compute SOC trajectory and earnings ──────────────
    let battery_capacity_watt = clampedStart;
    let earned_money          = startEarnedMoney;

    processedData.forEach(function(item) {
        if (item.hour_type === "charge") {
            const power_to_add = Math.min(calc_charge_rate, batt_max - battery_capacity_watt);
            if (power_to_add > 0) {
                battery_capacity_watt += power_to_add;
                earned_money          -= (power_to_add / charge_efficiency / 1000) * item.hour_price;
            }
            item.setpoint = G("max_charge_setpoint") || G("batt_charge_rate");

        } else if (item.hour_type === "discharge") {
            const power_to_sub = Math.max(0, Math.min(calc_discharge_rate, battery_capacity_watt - batt_min));
            if (power_to_sub > 0) {
                battery_capacity_watt -= power_to_sub;
                earned_money          += (power_to_sub * discharge_efficiency / 1000) * item.hour_price;
                item.setpoint          = -(G("max_discharge_setpoint"));
            } else {
                // Can't discharge (already at floor) → force idle
                item.hour_type = "idle";
                item.setpoint  = G("idle_rate") || 0;
            }

        } else {
            item.setpoint = G("idle_rate") || 0;
        }

        item.battery_capacity_watt       = Math.round(battery_capacity_watt);
        item.battery_capacity_percentage = parseFloat(((100.0 / batt_max) * battery_capacity_watt).toFixed(2));
        item.earned_money                = parseFloat(earned_money.toFixed(4));
    });

    return processedData;
}

// ═══════════════════════════════════════════════════════════════════════════════
// ENTRY POINTS
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Entry 1: Today-only calculation.
 * Called at 00:01 daily and on Node-RED startup (via inject once:true).
 * Runs a full single-day DP with the real current battery SOC.
 *
 * @param {object} json    - { datum, status, data[] } from Tibber/Combine node
 * @param {object} ctxRef  - In Node-RED: not needed (uses context directly).
 *                           In standalone: pass { scheme_today: null } to simulate.
 * @returns {object}       - { status, datum, data[] } for MQTT output
 */
function runToday(json, ctxRef) {
    if (!sanityCheck(json, 0)) return { status: false };

    const startSoc = getStartSocWatt();
    // In Node-RED skip slots that are already in the past; tests always start from 0.
    const nowIdx   = STANDALONE ? 0 : currentSlotIdx();

    // Run DP + post-passes only on current and future slots
    const futureData   = json.data.slice(nowIdx);
    const futureResult = calculate_charge_schema(futureData, startSoc, true, 0.0);
    const futureFilled = applySolarBalanceFill(futureResult, startSoc);
    const sbCount      = futureFilled.filter(function(s) { return s.hour_type === 'solarbalance'; }).length;
    if (sbCount > 0) warn("solarbalance fill: " + sbCount + " slots added");

    // Past slots: force idle at current SOC (actual history is unknown here)
    const batt_max  = G("batt_capacity") * G("max_soc") / 100;
    const idle_rate = G("idle_rate") || 0;
    const pastSlots = json.data.slice(0, nowIdx).map(function(slot) {
        return Object.assign({}, slot, {
            hour_type:                   'idle',
            setpoint:                    idle_rate,
            battery_capacity_watt:       Math.round(startSoc),
            battery_capacity_percentage: parseFloat(((100.0 / batt_max) * startSoc).toFixed(2)),
            earned_money:                0
        });
    });

    const todayFilled = pastSlots.concat(futureFilled);

    // Store indexed scheme for fast lookup and cross-day re-optimization.
    // Also write charge_scheme_today in array format for downstream consumers.
    if (!STANDALONE) {
        context.global.scheme_today       = buildSchemeObj(json.datum, todayFilled);
        context.global.charge_scheme_today = { status: true, datum: json.datum, data: todayFilled };
    } else if (ctxRef) {
        ctxRef.scheme_today = buildSchemeObj(json.datum, todayFilled);
    }

    warn("Today done: " + todayFilled.length + " slots, startSOC=" + Math.round(startSoc) + "Wh, nowIdx=" + nowIdx);
    return { status: true, datum: json.datum, data: todayFilled };
}

/**
 * Entry 2: Joint today+tomorrow calculation.
 * Called at 14:01 / 15:01 daily and on Node-RED startup when time >= 14:01.
 * Reads remaining today slots from context.global.scheme_today, combines with
 * tomorrow data, and runs a single DP pass for cross-day optimization.
 *
 * Returns an array of two messages: [updatedTodayMsg, tomorrowMsg].
 * In Node-RED these are sent sequentially on the same output wire to MQTT.
 *
 * @param {object} tomorrowJson - { datum, status, data[] } for tomorrow
 * @param {object} ctxRef       - In standalone: { scheme_today: <indexed obj> }
 * @returns {Array|object}      - [todayMsg, tomorrowMsg] on success, or single fallback msg
 */
function runTomorrow(tomorrowJson, ctxRef) {
    if (!sanityCheck(tomorrowJson, 1)) return { status: false };

    const todayScheme = STANDALONE
        ? (ctxRef && ctxRef.scheme_today)
        : context.global.scheme_today;

    if (!todayScheme || todayScheme.status !== true) {
        // No today scheme yet — optimize tomorrow standalone as a safe fallback
        warn("No scheme_today, optimizing tomorrow standalone");
        const startSoc = getStartSocWatt();
        const result   = calculate_charge_schema(tomorrowJson.data, startSoc, true, 0.0);
        const filled  = applySolarBalanceFill(result, startSoc);
        const sbCount = filled.filter(function(s) { return s.hour_type === 'solarbalance'; }).length;
        if (sbCount > 0) warn("solarbalance fill: " + sbCount + " slots added");
        if (!STANDALONE) {
            context.global.scheme_tomorrow       = buildSchemeObj(tomorrowJson.datum, filled);
            context.global.charge_scheme_tomorrow = { status: true, datum: tomorrowJson.datum, data: filled };
        } else if (ctxRef) {
            ctxRef.scheme_tomorrow = buildSchemeObj(tomorrowJson.datum, filled);
        }
        return { status: true, datum: tomorrowJson.datum, data: filled };
    }

    const nowIdx    = currentSlotIdx();
    const todayArr  = schemeObjToArray(todayScheme);

    // Strip schedule fields from remaining today so DP can re-decide
    const remainingToday = todayArr.slice(nowIdx).map(function(slot) {
        return { datum: slot.datum, hour_price: slot.hour_price, level: slot.level, forecast: slot.forecast || 0 };
    });
    const nRemaining = remainingToday.length;
    const nTomorrow  = tomorrowJson.data.length;

    // Carry earned money from already-completed today slots
    const prevSlot      = (nowIdx > 0) ? todayArr[nowIdx - 1] : null;
    const startEarned   = prevSlot ? (prevSlot.earned_money || 0.0) : 0.0;
    const startSoc      = getStartSocWatt();

    // Single DP pass over remaining today + all tomorrow
    // noChargeAfterLastDischarge=false here: we apply it per-day below
    const combined       = remainingToday.concat(tomorrowJson.data);
    const combinedResult = calculate_charge_schema(combined, startSoc, false, startEarned);

    // Apply noChargeAfterLastDischarge independently per day
    applyNoChargeAfterLastDischarge(combinedResult, 0, nRemaining);
    applyNoChargeAfterLastDischarge(combinedResult, nRemaining, nRemaining + nTomorrow);

    // Apply solarbalance fill across the combined span
    const filledResult = applySolarBalanceFill(combinedResult, startSoc);
    const sbCount = filledResult.filter(function(s) { return s.hour_type === 'solarbalance'; }).length;
    if (sbCount > 0) warn("solarbalance fill: " + sbCount + " slots added");

    const updatedTodaySlots = filledResult.slice(0, nRemaining);
    const tomorrowSlots     = filledResult.slice(nRemaining);

    // Reset earned_money for tomorrow slots back to zero-based.
    // The joint DP carries earned_money continuously from today's running total,
    // but consumers (Forecast.html chart, BattPlanTxt) expect tomorrow to start at 0.
    const earnedOffset = tomorrowSlots.length > 0 ? tomorrowSlots[0].earned_money : 0;
    tomorrowSlots.forEach(function(slot) {
        slot.earned_money = parseFloat((slot.earned_money - earnedOffset).toFixed(4));
    });

    // Persist updated schemes (indexed object for fast lookup) and
    // charge_scheme_* (array format) for downstream consumers.
    if (!STANDALONE) {
        context.global.scheme_today    = updateSchemeObj(todayScheme, nowIdx, updatedTodaySlots);
        context.global.scheme_tomorrow = buildSchemeObj(tomorrowJson.datum, tomorrowSlots);
        context.global.charge_scheme_today = {
            status: true,
            datum:  todayScheme.datum,
            data:   schemeObjToArray(context.global.scheme_today)
        };
        context.global.charge_scheme_tomorrow = {
            status: true,
            datum:  tomorrowJson.datum,
            data:   tomorrowSlots
        };
    } else if (ctxRef) {
        ctxRef.scheme_today    = updateSchemeObj(todayScheme, nowIdx, updatedTodaySlots);
        ctxRef.scheme_tomorrow = buildSchemeObj(tomorrowJson.datum, tomorrowSlots);
    }

    const socSource = (GD("batt_soc") != null) ? "actual(" + GD("batt_soc") + "%)" : "planned";
    warn("Joint done: remaining=" + nRemaining + " today + " + nTomorrow + " tomorrow, startSOC=" + Math.round(startSoc) + "Wh [" + socSource + "]");

    // Return two messages: updated today + full tomorrow
    const todayMsg = {
        topic:   "scheme_today",
        payload: { status: true, datum: todayScheme.datum, data: schemeObjToArray(STANDALONE ? ctxRef.scheme_today : context.global.scheme_today) }
    };
    const tomorrowMsg = {
        topic:   "scheme_tomorrow",
        payload: { status: true, datum: tomorrowJson.datum, data: tomorrowSlots }
    };
    return [todayMsg, tomorrowMsg];
}

// ═══════════════════════════════════════════════════════════════════════════════
// NODE-RED DISPATCH (entry point when running inside function node)
// ── CUT HERE: everything above this line goes into the function node ──────────
// ═══════════════════════════════════════════════════════════════════════════════

if (!STANDALONE) {
    // Node has 2 outputs:
    //   Output 1 → tibber_data/scheme_today/state
    //   Output 2 → tibber_data/scheme_tomorrow/state
    //
    // return [todayMsg, null]          → output 1 only (runToday)
    // return [todayMsg, tomorrowMsg]   → both outputs (runTomorrow joint result)
    // return [null, tomorrowMsg]       → output 2 only (runTomorrow fallback)

    const topicRoot = 'tibber_data';

    if (msg.topic.includes("scheme_today")) {
        const out = runToday(msg.payload);
        if (!out.status) return null;
        msg.payload = out;
        msg.topic   = topicRoot + '/scheme_today/state';
        msg.retain  = true;
        return [msg, null];

    } else if (msg.topic.includes("scheme_tomorrow")) {
        const out = runTomorrow(msg.payload);
        if (!out) return null;
        if (Array.isArray(out)) {
            out[0].topic  = topicRoot + '/scheme_today/state';
            out[0].retain = true;
            out[1].topic  = topicRoot + '/scheme_tomorrow/state';
            out[1].retain = true;
            return out;  // [todayMsg, tomorrowMsg] → output 1 + output 2
        }
        // Fallback: no scheme_today available, tomorrow standalone
        out.topic  = topicRoot + '/scheme_tomorrow/state';
        out.retain = true;
        return [null, out];

    } else {
        node.warn("OP9: unexpected topic: " + msg.topic);
        return null;
    }
}

// ═══════════════════════════════════════════════════════════════════════════════
// STANDALONE EXPORTS (used by runner.js)
// ═══════════════════════════════════════════════════════════════════════════════

if (STANDALONE) {
    module.exports = {
        runToday,
        runTomorrow,
        calculate_charge_schema,
        buildSchemeObj,
        schemeObjToArray,
        updateSchemeObj,
        currentSlotKey,
        currentSlotIdx,
        getStartSocWatt,
        CONFIG,
    };
}

// Schedule Solar Rerun
// Triggered by OP9 output 0 (today-only reruns) and output 1 (joint today+tomorrow run).
// Scans scheme_today for the first upcoming solarbalance slot and schedules a re-run at
// its LAST MINUTE (14 min after slot start). This fires before the slot ends so the
// battery mode setter picks up the recalculated plan for the next slot within 1 minute.
// Self-chains: each rerun produces a new scheme_today (output 0) -> this node -> next slot.

const MINS        = ["00", "15", "30", "45"];
const LAST_MIN_MS = 14 * 60 * 1000;  // 14 min into a 15-min slot = last minute

// Cancel any timer pending from the previous OP9 run
const prevTimer = context.get('solarRerunTimer');
if (prevTimer) {
    clearTimeout(prevTimer);
    context.set('solarRerunTimer', null);
}

const scheme = context.global.scheme_today;
if (!scheme || scheme.status === false) {
    node.status({fill:"grey", shape:"dot", text:"no scheme"});
    return null;
}

const now        = new Date();
const currentIdx = now.getHours() * 4 + Math.floor(now.getMinutes() / 15);

// Scan from current slot: covers a solarbalance slot that is already running
// (fires at its last minute if we're still within the first 14 min of it).
for (let i = currentIdx; i < 96; i++) {
    const h   = Math.floor(i / 4);
    const m   = i % 4;
    const key = ("0" + h).slice(-2) + ":" + MINS[m];
    const slot = scheme[key];
    if (slot && slot.hour_type === 'solarbalance') {
        const slotStart = new Date();
        slotStart.setHours(h, m * 15, 0, 0);
        const msUntil = (slotStart - now) + LAST_MIN_MS;
        if (msUntil <= 0) continue;  // last minute already passed, try next slot

        const minUntil = Math.round(msUntil / 60000);
        node.status({fill:"blue", shape:"ring", text:"⟳ end of " + key + " in " + minUntil + "min"});

        const timer = setTimeout(function() {
            node.status({fill:"green", shape:"dot", text:"⟳ triggered end of " + key});
            node.send({payload: 1, topic: 'solar_rerun'});
        }, msUntil);
        context.set('solarRerunTimer', timer);
        return null;
    }
}

node.status({fill:"grey", shape:"dot", text:"no upcoming solarbalance"});
return null;

// Solar Rerun: Stored Data
// Triggered by the solarbalance timer (Schedule Solar Rerun).
// If scheme_tomorrow exists (post-14:01), triggers the joint today+tomorrow DP so both
// schemes are recalculated with the actual live battery SOC.
// Before 14:01 (no tomorrow yet), falls back to today-only recalculation.
// OP9's getStartSocWatt() reads context.global.data.batt_soc at trigger time.

const tomorrow = context.global.charge_scheme_tomorrow;
const today    = context.global.charge_scheme_today;

if (tomorrow && tomorrow.status) {
    msg.payload = tomorrow;
    msg.topic   = "scheme_tomorrow";
} else if (today && today.status) {
    msg.payload = today;
    msg.topic   = "scheme_today";
} else {
    node.warn("Solar rerun: no stored scheme available in context");
    return null;
}

return msg;
